"use strict";(self.webpackChunkdammy=self.webpackChunkdammy||[]).push([[534],{5296:(e,n,a)=>{a.r(n),a.d(n,{data:()=>s});const s={key:"v-5c0dd206",path:"/overview/",title:"Overview",lang:"en-US",frontmatter:{},excerpt:"",headers:[{level:2,title:"What is dammy?",slug:"what-is-dammy",children:[{level:3,title:"What you can do",slug:"what-you-can-do",children:[]}]},{level:2,title:"Example",slug:"example",children:[]}],filePathRelative:"overview/README.md",git:{updatedTime:1779339404e3,contributors:[{name:"ontheroadjp",email:"dev@ontheroad.jp",commits:3}]}}},4992:(e,n,a)=>{a.r(n),a.d(n,{default:()=>r});const s=(0,a(6252).uE)('<h1 id="overview" tabindex="-1"><a class="header-anchor" href="#overview" aria-hidden="true">#</a> Overview</h1><h2 id="what-is-dammy" tabindex="-1"><a class="header-anchor" href="#what-is-dammy" aria-hidden="true">#</a> What is dammy?</h2><p><strong>dammy</strong> is a Bash script that instantly generates dummy files and directory trees for testing and development purposes.</p><p>Setting up test fixtures by hand — running <code>mkdir</code>, <code>touch</code>, and other commands one by one — is tedious and error-prone. dammy eliminates that friction with a single command.</p><h3 id="what-you-can-do" tabindex="-1"><a class="header-anchor" href="#what-you-can-do" aria-hidden="true">#</a> What you can do</h3><ul><li><strong>Generate test dummy files</strong> — Create any number of files with randomized names in one shot. Choose any file extension.</li><li><strong>Build directory hierarchies</strong> — Create deeply nested directories automatically. No need to pre-create parent directories.</li><li><strong>Use special characters in names</strong> — Generate files and directories whose names include symbols, whitespace, or Japanese (2-byte) characters. Useful for testing edge cases in file name handling.</li><li><strong>Generate dummy images for web development</strong> — When an image format is specified (jpg, png, gif, etc.), dammy produces actual image files using ImageMagick. Each image is a gray canvas with the resolution printed at the center — ready to drop into mockups or front-end tests.</li><li><strong>Preview before creating</strong> — The <code>--cold-run</code> flag shows you exactly what would be created, without touching the filesystem.</li></ul><h2 id="example" tabindex="-1"><a class="header-anchor" href="#example" aria-hidden="true">#</a> Example</h2><p>Run this single command:</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>dammy.sh hoge/<span class="token punctuation">{</span>foo,bar<span class="token punctuation">}</span>/piyo -n <span class="token number">3</span> --each --with-whitespace\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br></div></div><p>And you get the following tree instantly:</p><div class="language-text ext-text line-numbers-mode"><pre class="language-text"><code>hoge\n├── ) R a Y A .txt\n├── H t 8 9 h .txt\n├── \\ U X , ! .txt\n├── bar\n│   ├── ! + w 2 q .txt\n│   ├── , ) R ; c .txt\n│   ├── d P 9 6 i .txt\n│   └── piyo\n│       ├── % U 2 P L .txt\n│       ├── 5 R J j c .txt\n│       └── O S : 3 E .txt\n├── d M 6 2 x .txt\n├── foo\n│   ├── $ A P H _ .txt\n│   ├── J Z d &#39; a .txt\n│   ├── i W S _ 1 .txt\n│   └── piyo\n│       ├── : L w &amp; I .txt\n│       ├── A e @ j &amp; .txt\n│       └── r W 2 * ( .txt\n├── v @ R q j .txt\n└── y g R , 9 .txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br></div></div>',11),t={},r=(0,a(3744).Z)(t,[["render",function(e,n){return s}]])},3744:(e,n)=>{n.Z=(e,n)=>{const a=e.__vccOpts||e;for(const[e,s]of n)a[e]=s;return a}}}]);